"""Compiles port_gfx's GLSL shaders to SPIR-V and writes ../port_gfx_shaders.h (the arrays port_gfx.c uses), so the
recompilers that vendor port_gfx need no shader compiler. Run after changing a shader:

    python build_shaders.py <path to glslang.exe>   (Khronos glslang 16.6.0 or later)
"""
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
SHADERS = [('fullscreen.vert', 'PORT_GFX_FULLSCREEN_VERT'), ('blit.frag', 'PORT_GFX_BLIT_FRAG'),
           ('easu.frag', 'PORT_GFX_EASU_FRAG'), ('rcas.frag', 'PORT_GFX_RCAS_FRAG')]


def main():
    glslang = sys.argv[1] if len(sys.argv) > 1 else 'glslang'
    out = ['/* Generated by shaders/build_shaders.py from the shaders folder; do not edit. */',
           '#pragma once', '#include <stdint.h>', '']
    with tempfile.TemporaryDirectory() as tmp:
        for name, symbol in SHADERS:
            spv = Path(tmp) / (name + '.spv')
            subprocess.run([glslang, '-V', '--target-env', 'vulkan1.1', '-I' + str(HERE.parent / 'third_party/fsr'),
                            '-o', str(spv), str(HERE / name)], check=True, stdout=subprocess.DEVNULL)
            data = spv.read_bytes()
            words = [int.from_bytes(data[i:i + 4], 'little') for i in range(0, len(data), 4)]
            out.append(f'static const uint32_t {symbol}[] = {{')
            for i in range(0, len(words), 8):
                out.append('    ' + ', '.join(f'0x{w:08x}u' for w in words[i:i + 8]) + ',')
            out.append('};')
            out.append('')
    (HERE.parent / 'port_gfx_shaders.h').write_text('\n'.join(out), encoding='utf-8')


if __name__ == '__main__':
    main()
